// Read-only fixture friend over the pinned original private cache slots.
// No new product API/state, capture, clear, current or return call is added.
namespace ymcc::inputHost::sharedPower {
struct FixtureOwnershipInspector {
 static bool cache(const Cache& value)noexcept{return value.scope_!=nullptr;}
 static bool lifecycle(const RemoteOffers& value)noexcept{return value.lifecycle_!=nullptr;}
 static bool frame(const RemoteOffers& value)noexcept{return value.frame_!=nullptr;}
};
}

// Only the original full-cycle terminal owner calls this after its last Clear.
// No fresh capture/import, ledger erasure, synthetic Returned, or device action.
static json fixtureCurrentPublicPowerReturn=json::object();
static void fixtureObserveCurrentPublicPowerReturn(){
 using Runtime=ymcc::sleeppower::remote::NativeRemoteRuntime;
 using Transport=ymcc::sleeppower::remote::NativeRemoteTransport;
 auto* runtime=g_sharedNativeRemotePowerRuntimeGate.published(); // Read-only: cold exit stays cold.
 Transport* transport=runtime?runtime->transport():nullptr; // Borrow through original runtime lifetime.
 const bool debtBefore=g_msiDinputReturnOwed.load();
 const auto episodeBefore=g_msiDinputReturnDebtEpisode.load();
 auto localInputOwners=[&](){
  std::lock_guard<InputHostMutex> lock(g_inputHostMx);
  using Inspector=ymcc::inputHost::sharedPower::FixtureOwnershipInspector;
  return json{{"inputCache",Inspector::cache(g_inputHostInputPowerCache)},
   {"lifecycleCache",Inspector::cache(g_inputHostLifecyclePowerCache)},
   {"lifecycleOffer",Inspector::lifecycle(g_inputHostRemotePowerOffers)},
   {"frameOffer",Inspector::frame(g_inputHostRemotePowerOffers)},
   {"threadRequestScope",t_inputHostRequestPower!=nullptr},
   {"threadFrameSubmission",t_inputFrameSubmission!=nullptr},
   {"scope","existing Native Host transaction owners only; read without capture or clear"}};
 };
 auto snapshot=[&](){
  json value={{"runtimePublished",runtime!=nullptr},{"gateClosed",g_sharedNativeRemotePowerRuntimeGate.closed()},
   {"msiModeDebt",g_msiDinputReturnOwed.load()},{"msiModeDebtEpisode",g_msiDinputReturnDebtEpisode.load()}};
  if(runtime){auto& provider=runtime->provider();value["provider"]={{"open",provider.isOpen()},
   {"admissionOpen",provider.admissionOpen()},{"outstanding",provider.outstanding()},
   {"exitedConsumerDebt",provider.exitedConsumerDebtCount()},
   {"changeEventOwnedUntilRuntimeDestruction",provider.changeEvent()!=nullptr}};}
  if(transport)value["transport"]={{"running",transport->running()},{"activeRequests",transport->activeRequests()},
   {"pendingIo",transport->pendingIo()},{"trackedOffers",transport->trackedOffers()},
   {"trackedOfferCapacity",transport->trackedOfferCapacity()},{"servedRequests",transport->servedRequests()}};
  value["nativeInputOwners"]=localInputOwners();
  return value;
 };
 const auto before=snapshot();
 std::vector<std::weak_ptr<ymcc::sleeppower::remote::NativeScope>> observedBorrowers;
 json originalConsumers=json::array();bool waitSnapshotKnown=true;
 if(runtime){
  std::vector<ymcc::sleeppower::remote::NativeProvider::ConsumerWait> consumers;
  waitSnapshotKnown=runtime->provider().consumerWaits(consumers);
  for(const auto& consumer:consumers){
   observedBorrowers.emplace_back(consumer.scope);
   originalConsumers.push_back({{"consumerPid",consumer.scope->binding().consumer.pid},
    {"kernelWait",WaitForSingleObject(consumer.process,0)},
    {"lastSettlement",static_cast<unsigned>(consumer.scope->lastSettlement())}});
  }
 } // Release every diagnostic strong borrow before the real stop/join.
 finishSharedNativeRemotePower();
 const auto after=snapshot();
 unsigned heldBorrowers=0;for(const auto& weak:observedBorrowers)if(!weak.expired())++heldBorrowers;

 // Query the original debt reader with actual issued identities and this exact
 // provider birth. This is read-only and cannot invent a Returned receipt.
 json debtRows=json::array();
 const auto issued=ymcc::sleeppower::remote::issuedScopeIdentities.load(std::memory_order_acquire);
 ymcc::sleeppower::remote::ProcessIdentityV1 self;
 bool providerIdentityKnown=false;
 {ymcc::sleeppower::remote::ProcessHold selfHold;
  if(selfHold.bind(GetCurrentProcess()))providerIdentityKnown=ymcc::sleeppower::remote::processIdentity(selfHold.get(),self);
 } // Original held-process diagnostic owner returned before querying the ledger.
 const bool debtScanBounded=issued<=65536;
 if(runtime&&providerIdentityKnown&&debtScanBounded){
  for(std::uint64_t value=1;value<=issued;++value){
   ymcc::sleeppower::remote::NativeProvider::ExitedConsumerDebt debt;
   if(runtime->provider().exitedConsumerDebt({value,self.birth100ns},debt))
    debtRows.push_back({{"scopeLow",debt.binding.scope.low},{"scopeHigh",debt.binding.scope.high},
     {"consumerPid",debt.binding.consumer.pid},{"consumerBirth100ns",debt.binding.consumer.birth100ns},
     {"requestLow",debt.binding.request.low},{"purpose",static_cast<unsigned>(debt.binding.purpose)},
     {"lastOutcome",static_cast<unsigned>(debt.lastOutcome)},{"lastFlags",debt.lastFlags},
     {"kernelExitObserved",debt.kernelExitObserved},{"nativeBorrowerStillHeld",debt.nativeBorrowerStillHeld}});
  }
 }

 fixtureCurrentPublicPowerReturn={{"schemaVersion",1},{"stage","after-original-full-cycle-before-parent-exit"},
  {"parentPid",GetCurrentProcessId()},{"afterSourceOrdinal",cases.size()},{"originalChecks",checks},
  {"beforeStop",before},{"afterStop",after},{"consumerWaitSnapshotKnown",waitSnapshotKnown},{"exitedConsumerDebtRows",debtRows},{"issuedScopeIdentities",issued},{"providerIdentityKnown",providerIdentityKnown},{"debtScanBounded",debtScanBounded},
  {"originalConsumers",originalConsumers},{"observedRepresentativeBorrowersStillHeld",heldBorrowers},
  {"finishCalled",true},{"runtimeNotCreatedByObserver",g_sharedNativeRemotePowerRuntimeGate.published()==runtime},
  {"msiDebtUnchanged",g_msiDinputReturnOwed.load()==debtBefore&&g_msiDinputReturnDebtEpisode.load()==episodeBefore},
  {"nativeCacheDiagnosticsAvailable",true},{"managedChildCountersInChildReceipt",true},
  {"scope","actual original runtime/provider/transport terminal observation; cache and child-local counters remain unproven"}};
}

